PRAGMA foreign_keys = ON;
CREATE TABLE instance (id INTEGER PRIMARY KEY CHECK (id = 1), name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, instance_admin INTEGER NOT NULL DEFAULT 0, must_change_password INTEGER NOT NULL DEFAULT 1, disabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE memberships (org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('admin','member')), disabled INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(org_id,user_id));
CREATE INDEX memberships_user ON memberships(user_id);
CREATE TABLE domains (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL UNIQUE COLLATE NOCASE, ready INTEGER NOT NULL DEFAULT 0);
CREATE TABLE mailboxes (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), domain_id TEXT NOT NULL REFERENCES domains(id), address TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE mailbox_grants (mailbox_id TEXT NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(mailbox_id,user_id));
CREATE INDEX grants_user ON mailbox_grants(user_id);
CREATE TABLE blobs (id TEXT PRIMARY KEY, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id), owner_id TEXT REFERENCES users(id), draft_id TEXT, filename TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size >= 0), content_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE blob_chunks (blob_id TEXT NOT NULL REFERENCES blobs(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(blob_id,chunk_index));
CREATE TABLE messages (id TEXT PRIMARY KEY, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id), thread_id TEXT NOT NULL, dedup_key TEXT, message_id TEXT NOT NULL, in_reply_to TEXT NOT NULL DEFAULT '', references_json TEXT NOT NULL DEFAULT '[]', subject TEXT NOT NULL, sender TEXT NOT NULL, sender_name TEXT NOT NULL DEFAULT '', to_json TEXT NOT NULL, cc_json TEXT NOT NULL, reply_to TEXT NOT NULL DEFAULT '', text TEXT NOT NULL, html TEXT NOT NULL, snippet TEXT NOT NULL, received_at INTEGER NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), folder TEXT NOT NULL DEFAULT 'inbox', unread INTEGER NOT NULL DEFAULT 1, starred INTEGER NOT NULL DEFAULT 0, raw_blob_id TEXT REFERENCES blobs(id), UNIQUE(mailbox_id,dedup_key));
CREATE INDEX messages_mailbox_time ON messages(mailbox_id,received_at DESC);
CREATE INDEX messages_thread ON messages(mailbox_id,thread_id);
CREATE INDEX messages_message_id ON messages(mailbox_id,message_id);
CREATE TABLE message_attachments (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, blob_id TEXT NOT NULL REFERENCES blobs(id), PRIMARY KEY(message_id,blob_id));
CREATE TABLE labels (id TEXT PRIMARY KEY, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id), name TEXT NOT NULL, color TEXT NOT NULL, UNIQUE(mailbox_id,name));
CREATE TABLE message_labels (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE, PRIMARY KEY(message_id,label_id));
CREATE TABLE drafts (id TEXT PRIMARY KEY, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id), author_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, to_json TEXT NOT NULL, cc_json TEXT NOT NULL, bcc_json TEXT NOT NULL, subject TEXT NOT NULL, html TEXT NOT NULL, text TEXT NOT NULL, reply_to_message_id TEXT, attachment_ids TEXT NOT NULL DEFAULT '[]', updated_at INTEGER NOT NULL);
CREATE INDEX drafts_owner ON drafts(mailbox_id,author_id,updated_at DESC);
CREATE TABLE send_attempts (idempotency_key TEXT PRIMARY KEY, draft_id TEXT NOT NULL, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id), author_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('pending','sent','failed','unknown')), message_id TEXT, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX active_draft_send ON send_attempts(draft_id) WHERE status IN ('pending','sent','unknown');
CREATE TABLE audit_events (id TEXT PRIMARY KEY, org_id TEXT REFERENCES organizations(id), actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX audit_org_time ON audit_events(org_id,created_at DESC);
